import 'dart:async';

import 'package:core_base/core_base.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'ble_models.dart';
import 'ble_providers.dart';
import 'ble_service.dart';
import 'ble_session_state.dart';
import 'ble_vendor_adapter.dart';
import 'noop_ble_vendor_adapter.dart';

/// Injectable L2 vendor adapter. Override in App when chip SDK is ready.
final bleVendorAdapterProvider = Provider<BleVendorAdapter>(
  (ref) => const NoOpBleVendorAdapter(),
);

/// Shared BLE connection session for all device features.
final bleSessionProvider =
    NotifierProvider<BleSessionController, BleSessionState>(
  BleSessionController.new,
);

/// Manages active device connection on top of [BleService].
///
/// Permissions are intentionally **not** handled here — call
/// [BlePermissionGate.ensureScanPermissions] in Feature/App before [connect].
class BleSessionController extends Notifier<BleSessionState> {
  BleConnection? _connection;
  var _useVendorChannel = false;
  StreamSubscription<BleConnectionState>? _connectionSubscription;

  /// Active GATT link; null when disconnected or on vendor-only channel.
  BleConnection? get connection => _useVendorChannel ? null : _connection;

  /// Whether the session uses an L2 vendor channel instead of GATT.
  bool get useVendorChannel => _useVendorChannel;

  @override
  BleSessionState build() {
    ref.onDispose(() {
      unawaited(_connectionSubscription?.cancel());
    });

    final ble = ref.read(bleServiceProvider);
    _connectionSubscription = ble.connectionState.listen((next) {
      if (_useVendorChannel) {
        return;
      }
      state = state.copyWith(connectionState: next);
    });

    return const BleSessionState();
  }

  /// Connects to [deviceId] with optional [deviceName] for UI.
  Future<Result<void>> connect({
    required String deviceId,
    String? deviceName,
  }) async {
    state = state.copyWith(
      connectionState: BleConnectionState.connecting,
      deviceId: deviceId,
      deviceName: deviceName,
      clearError: true,
    );

    final vendor = ref.read(bleVendorAdapterProvider);
    final vendorResult = await vendor.connect(deviceId);
    if (vendorResult case Success()) {
      _useVendorChannel = true;
      _connection = null;
      state = state.copyWith(connectionState: BleConnectionState.connected);
      return const Result.success(null);
    }
    if (vendorResult case Failure(:final error)) {
      if (!_shouldFallbackToGatt(error)) {
        _resetSession();
        state = state.copyWith(
          connectionState: BleConnectionState.disconnected,
          lastError: error.message,
          clearDevice: true,
        );
        return Result.failure(error);
      }
    }

    final ble = ref.read(bleServiceProvider);
    final result = await ble.connect(deviceId);
    return result.fold(
      onSuccess: (link) {
        _useVendorChannel = false;
        _connection = link;
        state = state.copyWith(connectionState: BleConnectionState.connected);
        return const Result.success(null);
      },
      onFailure: (error) {
        _resetSession();
        state = state.copyWith(
          connectionState: BleConnectionState.disconnected,
          lastError: error.message,
          clearDevice: true,
        );
        return Result.failure(error);
      },
    );
  }

  /// Disconnects the active session.
  Future<Result<void>> disconnect() async {
    if (!state.isConnected && state.connectionState != BleConnectionState.connecting) {
      return const Result.success(null);
    }

    state = state.copyWith(connectionState: BleConnectionState.disconnecting);

    final Result<void> result;
    if (_useVendorChannel) {
      result = await ref.read(bleVendorAdapterProvider).disconnect();
    } else {
      final deviceId = state.deviceId;
      result = deviceId == null
          ? const Result.success(null)
          : await ref.read(bleServiceProvider).disconnect(deviceId);
    }

    _resetSession();
    state = state.copyWith(
      connectionState: BleConnectionState.disconnected,
      clearDevice: true,
      clearError: true,
    );
    return result;
  }

  /// Sends [frame] via vendor channel when active; otherwise fails.
  Future<Result<void>> sendVendorCommand(List<int> frame) async {
    if (!_useVendorChannel) {
      return const Result.failure(
        AppError(
          code: 'ble.vendor_not_active',
          message: 'No vendor channel active',
        ),
      );
    }
    return ref.read(bleVendorAdapterProvider).sendCommand(frame);
  }

  void _resetSession() {
    _connection = null;
    _useVendorChannel = false;
  }

  bool _shouldFallbackToGatt(AppError error) {
    return error.code == 'vendor.not_configured';
  }
}
