/// A unified result type for operation outcomes.
///
/// Use [Result.success] for successful values and [Result.failure] for errors.
/// Never throw raw exceptions across package boundaries — return [Result.failure] instead.
sealed class Result<T> {
  const Result._();

  /// Creates a successful result containing [value].
  const factory Result.success(T value) = Success<T>;

  /// Creates a failed result containing an [AppError].
  const factory Result.failure(AppError error) = Failure<T>;

  /// Maps the result to [R], calling [onSuccess] or [onFailure] accordingly.
  R fold<R>({
    required R Function(T value) onSuccess,
    required R Function(AppError error) onFailure,
  });
}

/// A successful [Result] wrapping a value of type [T].
final class Success<T> extends Result<T> {
  const Success(this.value) : super._();
  final T value;

  @override
  R fold<R>({
    required R Function(T value) onSuccess,
    required R Function(AppError error) onFailure,
  }) => onSuccess(value);

  @override
  bool operator ==(Object other) => other is Success<T> && other.value == value;

  @override
  int get hashCode => value.hashCode;
}

/// A failed [Result] wrapping an [AppError].
final class Failure<T> extends Result<T> {
  const Failure(this.error) : super._();
  final AppError error;

  @override
  R fold<R>({
    required R Function(T value) onSuccess,
    required R Function(AppError error) onFailure,
  }) => onFailure(error);

  @override
  bool operator ==(Object other) => other is Failure<T> && other.error == error;

  @override
  int get hashCode => error.hashCode;
}

/// A structured application error.
///
/// [code] is a machine-readable identifier (e.g. 'auth.token_expired').
/// [message] is a human-readable description.
/// [cause] is the optional underlying exception, never exposed across boundaries.
class AppError {
  const AppError({required this.code, required this.message, this.cause});

  final String code;
  final String message;
  final Object? cause;

  @override
  bool operator ==(Object other) =>
      other is AppError && other.code == code && other.message == message;

  @override
  int get hashCode => Object.hash(code, message);

  @override
  String toString() => 'AppError($code): $message';
}
